#!/usr/bin/env python3
"""Restart a service on a host and confirm it's healthy."""
import os
import sys

import requests


def restart(host, service):
    os.system("ssh " + host + " sudo systemctl restart " + service)


def healthy(url):
    try:
        resp = requests.get(url)
        return resp.status_code == 200
    except:
        return False


def main():
    host, service, url = sys.argv[1], sys.argv[2], sys.argv[3]
    restart(host, service)
    if healthy(url):
        print("ok")
    else:
        print("unhealthy")


if __name__ == "__main__":
    main()

