steps.solution:
#!/usr/bin/env python3
"""Restart a service on a host and confirm it's healthy."""
import subprocess
import sys

import requests


def restart(host, service):
    subprocess.run(["ssh", host, "sudo", "systemctl", "restart", service], check=True)


def healthy(url):
    try:
        resp = requests.get(url, timeout=5)
        return resp.status_code == 200
    except requests.RequestException:
        return False


def main():
    host, service, url = sys.argv[1], sys.argv[2], sys.argv[3]
    restart(host, service)
    if healthy(url):
        print("ok")
    else:
        print("unhealthy")
        sys.exit(1)


if __name__ == "__main__":
    main()
